/**
 * In-app auto-update (Tauri desktop only).
 *
 * The updater endpoint is the GitHub release feed (latest.json, generated by
 * tauri-action). Updates are signature-verified against the pubkey baked into
 * the app, so a clinic machine can update itself over any internet connection
 * without re-downloading the installer from the releases page.
 *
 * Flow: check() on a schedule → if an update exists, surface a non-blocking
 * banner (never force an interrupt mid-consultation) → user clicks
 * "Download update" → progress → NSIS installer runs in passive mode and the
 * app relaunches. On Windows the install step exits the app automatically,
 * so save pending DB writes first via the offline flush.
 *
 * ── Why there is a second path ─────────────────────────────────────────────
 * The plugin's check() is a black box that either works or throws. A single
 * failed install (NSIS registry entry missing after a per-machine install, a
 * proxy that strips the GitHub redirect, a WebView whose shell cache predates
 * the release) used to leave the machine reporting "You're on the latest
 * version" forever — the "stuck at 1.4.10" reports. So every check now also
 * reads the release feed directly and compares it with the running build:
 *
 *   - plugin finds an update      → mode "installer" (self-install, signed)
 *   - plugin fails/returns none,
 *     but the feed is newer       → mode "manual" (open the installer URL)
 *   - both fail                   → recorded in diagnostics, shown in Settings
 *
 * Failures are never silent any more: `subscribeToDiagnostics` carries the
 * last error, the last check time, and whether the feed is reachable.
 */

import { check, type Update } from "@tauri-apps/plugin-updater";
import { relaunch } from "@tauri-apps/plugin-process";
import { isTauriDesktop, flushDatabase } from "@/offline/activate";
import { saveUpdateNotesForNextBoot } from "@/components/update-applied-banner";
import { openExternalUrl } from "@/lib/open-external";
import { isNewer } from "@/lib/version";

export interface UpdateState {
  /** Update metadata available from the feed. */
  version: string;
  notes: string;
  /** "available" → idle prompt; "downloading" → progress 0..1; "ready" → restart pending. */
  phase: "available" | "downloading" | "ready";
  /** 0..1 download progress; only meaningful while downloading. */
  progress: number;
  /**
   * How this update can be applied:
   *  - "installer": the signed in-app updater can download and install it.
   *  - "manual": self-install is unavailable on this machine, so the UI
   *    offers the installer download for the user to run once.
   *  - "repair": the binary is already current (the plugin reports no update)
   *    while the running UI is older — a stale service-worker shell. The UI
   *    offers "Repair cached files" instead of another download.
   */
  mode: "installer" | "manual" | "repair";
  /** Direct installer URL for "manual" mode (release asset or release page). */
  downloadUrl?: string;
}

export interface UpdateDiagnostics {
  /** When the last check completed (ms epoch), or null if none has run. */
  lastCheckedAt: number | null;
  /** Human-readable reason the last check could not offer a self-install. */
  lastError: string | null;
  /** Version advertised by the release feed, even if self-install is broken. */
  feedVersion: string | null;
  /** True when the signed in-app updater is usable on this machine. */
  selfInstall: boolean;
}

type Listener = (state: UpdateState | null) => void;
type DiagnosticsListener = (diag: UpdateDiagnostics) => void;

let listeners = new Set<Listener>();
let diagnosticsListeners = new Set<DiagnosticsListener>();
let state: UpdateState | null = null;
let diagnostics: UpdateDiagnostics = {
  lastCheckedAt: null,
  lastError: null,
  feedVersion: null,
  selfInstall: true,
};
let checkTimer: number | null = null;

/**
 * The release feed the Tauri updater reads is a release *asset*, and GitHub
 * serves release assets without CORS headers — a webview `fetch` of it is
 * blocked. The REST API returns the same release (version, notes, installer
 * URLs) with `access-control-allow-origin: *`, so the fallback probe uses it.
 * Unauthenticated, 60 requests/hour: one check per hour is far inside that.
 */
const FEED_URL = "https://api.github.com/repos/azshifat007/Dental-Canvas/releases/latest";
const RELEASES_PAGE = "https://github.com/azshifat007/Dental-Canvas/releases/latest";

/** Notify React subscribers (the settings card / banner). */
function emit(next: UpdateState | null): void {
  state = next;
  for (const l of listeners) l(state);
}

function emitDiagnostics(patch: Partial<UpdateDiagnostics>): void {
  diagnostics = { ...diagnostics, ...patch };
  for (const l of diagnosticsListeners) l(diagnostics);
}

export function subscribeToUpdates(listener: Listener): () => void {
  listeners.add(listener);
  listener(state);
  return () => listeners.delete(listener);
}

export function subscribeToDiagnostics(listener: DiagnosticsListener): () => void {
  diagnosticsListeners.add(listener);
  listener(diagnostics);
  return () => diagnosticsListeners.delete(listener);
}

export function getUpdateState(): UpdateState | null {
  return state;
}

export function getUpdateDiagnostics(): UpdateDiagnostics {
  return diagnostics;
}

export function isUpdateSupported(): boolean {
  return isTauriDesktop();
}

/** The release page — always valid, even when every automated path fails. */
export function releasesPageUrl(): string {
  return RELEASES_PAGE;
}

// ── Release feed (direct) ─────────────────────────────────────────────────

interface FeedAsset {
  name?: string;
  browser_download_url?: string;
}
interface Feed {
  tag_name?: string;
  body?: string;
  html_url?: string;
  assets?: FeedAsset[];
}

/**
 * Read the newest published release from the GitHub API.
 *
 * This is the same release the Tauri updater reads, fetched in the webview
 * instead of Rust. Nothing here is installed automatically — it only tells the
 * UI which version exists and where the installer lives — so no signature is
 * involved, and it works on machines where the plugin path is broken.
 * Returns null when offline, rate-limited, or unparseable.
 */
async function fetchFeed(): Promise<Feed | null> {
  try {
    const res = await fetch(FEED_URL, {
      cache: "no-store",
      headers: { Accept: "application/vnd.github+json" },
      signal: AbortSignal.timeout(10_000),
    });
    if (!res.ok) return null;
    return (await res.json()) as Feed;
  } catch {
    return null;
  }
}

/** Pick the installer URL for this OS from the release's assets. */
function pickDownloadUrl(feed: Feed): string {
  const assets = (feed.assets ?? []).filter(
    (a): a is { name: string; browser_download_url: string } =>
      Boolean(a.name && a.browser_download_url),
  );
  const patterns = /windows/i.test(navigator.userAgent)
    ? [/x64-setup\.exe$/i, /setup\.exe$/i]
    : /mac/i.test(navigator.userAgent)
      ? [/\.dmg$/i]
      : [/\.AppImage$/i, /\.deb$/i];
  for (const pattern of patterns) {
    const hit = assets.find((a) => pattern.test(a.name));
    if (hit) return hit.browser_download_url;
  }
  // Any installer beats nothing; the release page lists them all.
  return feed.html_url || RELEASES_PAGE;
}

function errorMessage(err: unknown): string {
  if (err instanceof Error && err.message) return err.message;
  const text = String(err ?? "").trim();
  return text || "unknown error";
}

// ── Checking ──────────────────────────────────────────────────────────────

let checking: Promise<string | null> | null = null;

/**
 * Query the update feed once. Safe to call repeatedly: calls are deduplicated
 * and the hourly timer lives in `startUpdatePoller`.
 *
 * Returns the newer version if one is known, else null.
 */
export function checkForUpdates(): Promise<string | null> {
  if (!isUpdateSupported()) return Promise.resolve(null);
  if (checking) return checking;
  checking = (async () => {
    let pluginError: string | null = null;
    let update: Update | null = null;

    try {
      update = await check({ timeout: 15_000 });
    } catch (err) {
      pluginError = errorMessage(err);
    }

    if (update) {
      if (state?.phase === "downloading") return state.version; // already on it
      emit({
        version: update.version,
        notes: update.body ?? "",
        phase: "available",
        progress: 0,
        mode: "installer",
      });
      emitDiagnostics({
        lastCheckedAt: Date.now(),
        lastError: null,
        feedVersion: update.version,
        selfInstall: true,
      });
      return update.version;
    }

    // Plugin says "nothing" or failed. Ask the feed directly: a newer version
    // there means this machine cannot self-install but MUST still tell the
    // user an update exists (and where to get it).
    const feed = await fetchFeed();
    const feedVersion = (feed?.tag_name ?? "").replace(/^v/i, "") || null;
    const selfInstall = pluginError === null;
    emitDiagnostics({
      lastCheckedAt: Date.now(),
      lastError: pluginError,
      feedVersion,
      selfInstall,
    });

    if (feedVersion && isNewer(feedVersion, __APP_VERSION__)) {
      if (state?.phase === "downloading") return state.version;
      // A clean "no update" from the plugin means the BINARY is already at
      // (or beyond) the feed version while this page is older: the update was
      // installed but the UI is still served from a stale shell cache. That is
      // the "stuck on an old version" machine — repairing the cache is the fix,
      // re-installing the same version is not.
      emit({
        version: feedVersion,
        notes: (feed?.body ?? "").trim(),
        phase: "available",
        progress: 0,
        mode: pluginError === null ? "repair" : "manual",
        downloadUrl: pickDownloadUrl(feed as Feed),
      });
      return feedVersion;
    }

    return null;
  })();
  return checking.finally(() => {
    checking = null;
  });
}

/**
 * Download and install the pending update via the signed in-app updater, then
 * relaunch. The returned promise resolves when the installer has been launched
 * — on Windows the app is killed by the installer at that point.
 */
export async function installUpdate(): Promise<void> {
  if (!isUpdateSupported()) return;
  const current = state;
  if (!current) return;
  if (current.mode === "repair") {
    await repairCachedAppFiles();
    return;
  }
  if (current.mode === "manual") {
    await openManualUpdate();
    return;
  }
  emit({ ...current, phase: "downloading", progress: 0 });
  // Re-check to obtain a fresh Update handle (handles are single-use).
  const update = await check({ timeout: 15_000 });
  if (!update) {
    emit(null);
    emitDiagnostics({ lastError: "the update feed no longer offers this version" });
    return;
  }
  let total = 0;
  await update.downloadAndInstall((event) => {
    switch (event.event) {
      case "Started":
        total = event.data.contentLength ?? 0;
        break;
      case "Progress":
        if (total > 0) {
          emit({
            ...state!,
            phase: "downloading",
            progress: Math.min(0.99, (state!.progress * total + event.data.chunkLength) / total),
          });
        }
        break;
      case "Finished":
        break;
    }
  });
  // The NSIS installer is about to terminate this process on Windows; push
  // any debounced DB writes to IndexedDB first (best effort, fire-and-forget).
  flushDatabase();
  // Save the changelog so the post-update banner can greet the user with it
  // after the relaunch (the fresh process has no in-memory update state).
  saveUpdateNotesForNextBoot(update.version, current.notes);
  emit({ version: update.version, notes: current.notes, phase: "ready", progress: 1, mode: "installer" });
  await relaunch();
}

/** Open the installer for a machine that cannot self-install. */
export async function openManualUpdate(): Promise<void> {
  const url = state?.downloadUrl ?? RELEASES_PAGE;
  await openExternalUrl(url);
}

/**
 * Throw away the cached app shell and service worker, then reload.
 *
 * This is the in-app version of the "stale UI" recovery: if the binary has
 * been updated but the page is still served from an old service-worker cache,
 * the UI keeps reporting the old version and the updater never offers
 * anything again. Only HTTP caches and worker registrations are touched —
 * the clinic database lives in IndexedDB, which is deliberately left alone.
 */
export async function repairCachedAppFiles(): Promise<void> {
  flushDatabase();
  try {
    if ("serviceWorker" in navigator) {
      const registrations = await navigator.serviceWorker.getRegistrations();
      await Promise.all(registrations.map((r) => r.unregister().catch(() => false)));
    }
  } catch {
    // nothing registered — fine
  }
  try {
    const keys = await caches.keys();
    await Promise.all(keys.map((k) => caches.delete(k).catch(() => false)));
  } catch {
    // no Cache Storage — fine
  }
  window.location.reload();
}

/** Hourly re-check; the clinic leaves the app open all day. */
const CHECK_INTERVAL_MS = 60 * 60 * 1000;

/**
 * Start the background update poller. Mount once from the app shell
 * (desktop only); returns a cleanup function.
 */
export function startUpdatePoller(): () => void {
  if (!isUpdateSupported()) return () => undefined;
  // Give the app time to boot and the clinic a moment before the first probe.
  const initial = window.setTimeout(() => {
    void checkForUpdates();
    checkTimer = window.setInterval(() => void checkForUpdates(), CHECK_INTERVAL_MS);
  }, 60_000);
  return () => {
    window.clearTimeout(initial);
    if (checkTimer !== null) window.clearInterval(checkTimer);
  };
}

/** Reset module state for tests. */
export function __resetUpdateStateForTests(): void {
  listeners = new Set();
  diagnosticsListeners = new Set();
  state = null;
  diagnostics = { lastCheckedAt: null, lastError: null, feedVersion: null, selfInstall: true };
  checking = null;
  if (checkTimer !== null) {
    window.clearInterval(checkTimer);
    checkTimer = null;
  }
}
